<script setup lang="ts">
import { ref, computed, onMounted } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useSession } from '../stores/session'
import { api, dateText, statusText } from '../api'
import { useCourseScope } from '../useCourseScope'
import Icon from '../components/Icon.vue'
import EmptyState from '../components/EmptyState.vue'
const scope=useCourseScope(), session=useSession(), rows=ref<any[]>([]), search=ref(''), loading=ref(true), uploading=ref(false), upload=ref<HTMLInputElement>(), selected=ref<any>(null), drawer=ref(false), sortDesc=ref(true)
const visible=computed(()=>rows.value.filter(r=>r.filename.toLowerCase().includes(search.value.toLowerCase())).sort((a,b)=>sortDesc.value?b.id-a.id:a.id-b.id))
const ready=computed(()=>rows.value.filter(r=>r.status==='ready').length), chunks=computed(()=>rows.value.reduce((s,r)=>s+r.chunks,0))
const loadError=ref(false)
async function refresh(){scope.stop();try{const data=await api.get(`/courses/${scope.courseId}/materials`);if(!scope.active())return;rows.value=data;loadError.value=false;if(data.some((r:any)=>['pending','processing','indexing'].includes(r.status)))scope.schedule(refresh)}catch{if(scope.active())loadError.value=true}}
async function load(){loading.value=true;try{await refresh()}finally{if(scope.active())loading.value=false}}
onMounted(load)
async function handleUpload(event:Event){const files=(event.target as HTMLInputElement).files;if(!files?.length)return;uploading.value=true;try{for(const file of Array.from(files)){const form=new FormData();form.append('file',file);const r=await api.post(`/courses/${scope.courseId}/materials`,form);if(!scope.active())return;r.status==='failed'?ElMessage.warning('文件已保存，但解析失败，请查看原因'):ElMessage.success(r.status==='ready'?'资料已解析并入库':'资料已上传，等待解析与索引')}await load()}finally{uploading.value=false;if(upload.value)upload.value.value=''}}
async function preview(row:any){const data=await api.get(`/materials/${row.id}`);if(!scope.active())return;selected.value=data;drawer.value=true}
async function retry(row:any){uploading.value=true;try{await api.post(`/materials/${row.id}/retry`);await load()}finally{uploading.value=false}}
async function remove(row:any){try{await ElMessageBox.confirm('删除后，此资料将不再参与新的课程问答，历史引用快照仍保留。','删除课程资料',{confirmButtonText:'确认删除',cancelButtonText:'取消',type:'warning'});await api.delete(`/materials/${row.id}`);await load();ElMessage.success('资料已从知识库移除')}catch{}}
</script>
<template>
  <div class="page-heading"><div><span class="eyebrow">COURSE KNOWLEDGE · GROUNDED ANSWERS</span><h1>好回答，从可靠的资料开始</h1><p>上传课程内容，查看知识片段，让每一条引用都有据可查。</p></div><input ref="upload" data-testid="material-upload" type="file" multiple accept=".pdf,.pptx,.docx,.txt,.md,.srt,.vtt" hidden @change="handleUpload" /><button class="btn btn-primary" :disabled="uploading" @click="upload?.click()"><Icon :name="uploading?'refresh':'upload'" :size="17" />{{ uploading?'正在上传资料…':'上传课程资料' }}</button></div>
  <div class="knowledge-stats"><div class="panel"><span class="stat-icon blue"><Icon name="folder" :size="22" /></span><div><b>{{ rows.length }}<small>份</small></b><span>课程资料</span></div></div><div class="panel"><span class="stat-icon teal"><Icon name="badge" :size="22" /></span><div><b>{{ ready }}<small>份</small></b><span>已就绪资料</span></div></div><div class="panel"><span class="stat-icon purple"><Icon name="layers" :size="22" /></span><div><b>{{ chunks }}<small>段</small></b><span>可追溯知识片段</span></div></div></div>
  <div class="upload-hint"><Icon name="file" :size="22" /><div><b>支持 PDF / PPTX / DOCX / TXT / MD / SRT / VTT</b><p>单文件最大 20 MB。PDF 与 PPTX 保留实际页序，Word 按段落定位。扫描图片需先进行 OCR。</p></div><span class="tag blue">按课程隔离</span></div>
  <div v-if="loadError" class="error-box">资料状态刷新失败，请重新加载。</div><button class="text-link task-refresh" @click="load"><Icon name="refresh" :size="14" />刷新资料状态</button><section class="panel"><div class="toolbar"><div class="section-heading"><h3>全部课程资料</h3><span class="count-badge">{{ rows.length }}</span></div><div class="search-box"><Icon name="search" :size="17" /><input v-model="search" placeholder="搜索资料名称" aria-label="搜索资料" /></div></div><div v-loading="loading" class="table-scroll"><table class="data-table"><thead><tr><th>资料名称</th><th>入库状态</th><th>知识片段</th><th><button class="table-sort" @click="sortDesc=!sortDesc">上传时间 <Icon name="down" :size="12" /></button></th><th>操作</th></tr></thead><tbody><tr v-for="m in visible" :key="m.id"><td><div class="file-cell"><span class="file-icon"><Icon name="file" :size="23" /></span><div><b>{{ m.filename }}</b><small>{{ (m.size/1024).toFixed(1) }} KB <span v-if="m.is_seed">· 演示样例</span></small></div></div></td><td><span :class="['tag',m.status==='ready'?'green':m.status==='failed'?'orange':'blue']"><span class="status-dot"></span>{{ statusText[m.status]||m.status }}</span><p v-if="m.error" class="table-error">{{ m.error }}</p></td><td><strong>{{ m.chunks }}</strong><small class="muted"> 段</small></td><td class="muted small">{{ dateText(m.created_at,true) }}</td><td><div class="table-actions"><button class="text-link" data-testid="material-preview" @click="preview(m)">预览</button><button v-if="m.status==='failed'" class="text-link" :disabled="uploading" @click="retry(m)">重试</button><button class="icon-btn" aria-label="下载资料" @click="api.download(m.id,m.filename)"><Icon name="download" :size="16" /></button><button class="icon-btn danger-hover" aria-label="删除资料" @click="remove(m)"><Icon name="trash" :size="16" /></button></div></td></tr></tbody></table></div><EmptyState v-if="!loading&&!visible.length" title="课程知识库还在等待第一份资料" description="上传文字课件后，即可预览片段并用于课程问答。" /></section>
  <el-drawer v-model="drawer" title="知识片段" size="550px"><template v-if="selected"><h2>{{ selected.filename }}</h2><p class="muted small">{{ selected.chunks }} 个片段 · {{ selected.pages }} 个来源位置</p><div v-if="selected.error" class="error-box">{{ selected.error }}</div><div v-for="(s,i) in selected.segments" :key="s.id" class="segment-card"><div><span class="tag blue">{{ s.location }}</span><small class="muted">#{{ Number(i)+1 }}</small></div><p>{{ s.text }}</p></div></template></el-drawer>
</template>
